                                        $scope.importFormSettings.screenY = $scope.importFormSettings.screenModeTemp[0].screenCustom[0].y;
                                        $scope.importFormSettings.screenWidth = $scope.importFormSettings.screenModeTemp[0].screenCustom[0].width;
