        //Upload image
        $scope.uploadFileOnly = function (event) {
            $rootScope.$emit("ShowLoading");
            var reqType = "chat";
            var fileData = event;
            var files = fileData.files;
            if (files.length > 0) {
                angular.forEach(files, function (fileinfo) {
                    $rootScope.$emit("ShowLoading");
                    var fd = new FormData();
                    fd.append('file', fileinfo, fileinfo.name);
                    var userId = $scope.userDetail.Id;
                    var uid = $scope.userDetail.uid;
                    $scope.paramDetails.roomId = $scope.roomChatDetails.roomId;
                    $scope.paramDetails.message = "";
                    localStorage.setItem($scope.paramDetails.roomId, $scope.roomChatDetails.roomId);
                    mainService.uploadFile("UploadFile", fd, reqType, uid, "", "", "", "", false, userId)
                        .then(function (response) {
                            if (response.data != null && angular.isDefined(response.data)) {
                                if (angular.isDefined(response.data)) {
                                    $("input:hidden[name=filelink]").attr('value', "");
                                    if (response.data.code == 200) {
                                        response.data.fileUrl = response.data.fileUrl.replace('~', '');
                                        $scope.paramDetails.filePath = response.data.fileUrl;
                                        signalR.start(function () {
                                        signalR.server().send($scope.paramDetails);
                                        });
                                        $("#fileUpload").val("")
                                        $("input:hidden[name=filelink]").attr('value', response.data.fileUrl);
                                    } else {
                                        notifierService.notifySweetAlertMessage('error', 'File', response.data.message);
                                    }
                                    $rootScope.$emit("HideLoading");
                                }

                            }
                        }
                            , function (err) {
                                console.log("some error occured." + err);
                                $rootScope.$emit("HideLoading");
                            });
                });
            }
        };

