                param.action = 2;
                param.AutoId = $stateParams.Id;
                if (!DataService.isEmpty($scope.freshEntryformGroupKey))
                    param.formGroupKey = $scope.freshEntryformGroupKey;
                else
                    param.formGroupKey = $scope.formGroupKey;
