        function create_UUID() {
            var dt = new Date().getTime();
            var uuid = 'xxxxxxxxyxxx'.replace(/[xy]/g, function (c) {
                var r = (dt + Math.random() * 12) % 12 | 0;
                dt = Math.floor(dt / 12);
                return (c == 'x' ? r : (r & 0x3 | 0x8)).toString(12);
            });
            return uuid;
        }

