        $scope.fileUploadDataEntry = function (id) {
            //console.log('hitted');
            var oFReader = new FileReader();
            var files = document.getElementById(id).files;


            if (files.length > 1) {
                getMultipleFiles(id);
            }
            else if (files.length == 1) {

                if (files[0].type.match('image.*')) {
                    oFReader.readAsDataURL(files[0]);
                    oFReader.onload = function (oFREvent) {


                        document.getElementById("uploadPreview_" + id).src = oFREvent.target.result;

                        $("#uploadPreview_" + id).parent().parent().find('.file-title').html('');



                        $scope.removeHidden(id);
                        //var elem=" <div class='col-sm-12 attachments' data-name='file_1585050896437'><input type='hidden' name='fieldKey' value='7rIoJxFwPKN8'><input type='hidden' name='filePath' value=''><div class='col-sm-4 figure single-image hidden'><img class='scaled' id='uploadPreview_"+id+"' src='' height='100' alt=''><p class='file-title'></p><span class='img-wrapclose img-close single-file'>×</span></div><div class='figure single-file file-attachments hidden'><i class='far fa-file-alt fa-2x'></i> <p><a href='#' download=''><b></b></a></p><span class='img-wrapclose file-close single-file'>×</span> </div></div>";
                        // $("#uploadPreview_" + id).parent().parent().append(elem);

                    }

                }
                else {
                    $('#uploadPreview_' + id).removeAttr('src');
                    $('#uploadPreview_' + id).parent().addClass('hidden');
                    var fileAttachments = $('#' + id).parent().parents('.form-group').find('.attachments .file-attachments');
                    fileAttachments.find('p').append('<b>' + files.name + '</b>');
                    fileAttachments.removeClass("hidden");
                    $("input:hidden[name=" + id + "]").attr('value', "null");
                }


            };
            $scope.uploadFileOnly(files, id);

        };

        $scope.uploadFileOnly = function (element, id) {
            if (angular.isDefined(element)) {
                var fileData = element;
                var fd = new FormData();
                angular.forEach(fileData, function (value, key) {
                    fd.append(key, value);
                });
                //fd.append('file', fileData);
                var uid = $scope.userDetail.uid;
                var userId = $scope.userDetail.Id;
                mainService.uploadFile("UploadFile", fd, "", uid, "", "", "", "", false, userId)
                    .then(function (response) {
                        if (response.data != null && angular.isDefined(response.data)) {
                            if (angular.isDefined(response.data)) {
                                $("input:hidden[name=" + id + "]").attr('value', "");
                                if (response.data.code == 200) {
                                    console.log("uploaded Successfully");

                                    $("input:hidden[name=" + id + "]").attr('value', response.data.fileUrl);

                                } else {
                                    notifierService.notifySweetAlertMessage('error', 'File', response.data.message);
                                }
                                $rootScope.$emit("HideLoading");
                            }

                        }
                    }
                        , function (err) {
                            console.log("some error occured." + err);
                            $rootScope.$emit("HideLoading");
                        });
            }
        };

