                console.log(a);
                if (a.length < 6)
                    return "";
                else
                    return '<img src="' + $scope.baseurl + a[1] + '/' + a[2] + '/' + a[3] + '/' + a[4] + '/' + a[5] + '" width="' + formatterParams.width + '" height="' + formatterParams.height + '">';
