    FormGeneratorApp.controller('CreateContactApplicationController', function ($scope, $rootScope, $http, $location, $window, mainService, notifierService, $state, DataService) {
        $scope.param = {};
        $scope.enterdVal = {};
        $scope.init = function () {
            var webActions = '<div class="pull-right text-right rightbtn">\n\
                            <a href="#/" class="btn btn-primary pull-left redirectMenuPage" title="Home"><i class="fa fa-home"></i></a>\n\
                            <a href="#/chat/summary" class="btn btn-primary pull-left chatSummary" title="Chat"><i class="fa fa-commenting"></i ></a >\n\  \n\ </div > ';
            $(".card-header").append(webActions);


        };


        $scope.onsubmit = function () {

            //alert($scope.enterdVal.value);
            $scope.param.action = 5;
            $scope.param.contactUserName = $scope.enterdVal.value;
            $scope.param.userId = JSON.parse(localStorage.detail).Id;
            $scope.param.created_by = JSON.parse(localStorage.detail).Id;
            $scope.param.update_by = JSON.parse(localStorage.detail).Id;
            $scope.param.chatted = "No";
            if (DataService.isEmpty($scope.param.contactUserName)) {
                notifierService.notifyMessage('error', 'contact', 'please enter contact Username');
                return false;
            }
            $rootScope.$emit("ShowLoading");
            mainService.manageApplication("ManageUserContact", $scope.param)
                .then(function (response) {
                    console.log(response.data);
                    if (response.data != null && angular.isDefined(response.data)) {
                        if (response.data.length > 0) {
                            var exists = {};
                            exists = response.data[0];
                            //   var temp = {};
                            //  temp.applicationId = exists.applicationId;
                            // temp.applicationTitle = $scope.NewAppParam.applicationTitle;
                            //  console.log(temp);
                            //   $scope.applicationList.push(temp);
                            // $scope.topicParamRedirect.applicationId = temp.applicationId;
                            if (exists.res == 1) {
                                notifierService.notifyMessage('success', 'contact', exists.Message);

                                $state.go('contactlist', { reload: true, inherit: false });
                            }

                            else
                                notifierService.notifyMessage('error', 'contact', exists.Message);





                        }
                        $rootScope.$emit("HideLoading");
                    }
                }, function (err) {
                    $rootScope.$emit("HideLoading");
                    console.log("some error occured." + err);
                });
        }


        $scope.init();



    });
