    FormGeneratorApp.controller('userProfileUpdateController', function ($scope, notifierService, $rootScope, $http, $location, $window, $state, DataService, mainService, $timeout) {
        $scope.init = function () {
            var webActions = '<div class="pull-right text-right rightbtn">\n\
                            <a href="#/" class="btn btn-primary pull-left redirectMenuPage" title="Home"><i class="fa fa-home"></i></a>\n\
                            <a href="#/chat/summary" class="btn btn-primary pull-left chatSummary" title="Chat"><i class="fa fa-commenting"></i ></a >\n\  \n\ </div > ';
            $(".card-header").append(webActions);
            $scope.userDetail = mainService.loginDetails();
            $scope.userData = {};
            var param = {};
            param.action = 3;
            param.Id = $scope.userDetail.Id;

            $scope.getProfileDetail(param);
        };
        $scope.getProfileDetail = function (param) {
            mainService.manageProfile("profile", param)
                .then(function (response) {
                    if (response.data != null && angular.isDefined(response.data)) {

                        $scope.userData = response.data;
                        var isPhoneVerified = $scope.userData.phoneVerified;


                        setTimeout(function () {
                            if (isPhoneVerified === "Yes") {
                                $("#verified-message").removeClass("hide");
                                $("#validate-phone").addClass("hide");

                            }
                            else {
                                $("#verified-message").addClass("hide");
                                $("#validate-phone").removeClass("hide");

                            }


                        }, 1000);



                        console.log($scope.userData);
                    }

                }, function (err) {
                    console.log("some error occured." + err);
                });

        };
        function verifyCode() {

            alert($('#txtVerificationCode').val());
        };
        $scope.submitProfile = function () {
            var param = $scope.userData;
            param.action = 4;
            mainService.manageProfile("profile", param)
                .then(function (response) {
                    if (response.data != null && angular.isDefined(response.data)) {
                        var data = response.data;
                        if (data.res == 1) {
                            notifierService.notifyMessage('success', 'profile updated', data.Message);
                            $timeout(function () {
                                localStorage.setItem("detail", JSON.stringify(data));
                            }, 600);

                            location.reload(true);
                        } else {
                            notifierService.notifyMessage('error', 'failed', data.Message);
                        }
                    }

                }, function (err) {
                    console.log("some error occured." + err);
                });
        }
        $scope.phoneVerification = function () {
            window.swal({
                title: "Sending Verification Code...",
                text: "Please wait",
                imageUrl: "images/ajaxloader.gif",
                showConfirmButton: false,
                allowOutsideClick: false
            });


            var code = Math.floor(1000 + Math.random() * 9000);
            console.log(code);
            var param = {};
            param.isVerificationReq = true;
            param.verificationCode = code;
            param.phoneNumber = $scope.userData.phoneNumber;
            mainService.manageProfile("phoneVerification", param)
                .then(function (response) {
                    if (response.data != null && angular.isDefined(response.data)) {
                        var data = response.data;
                        if (data.res == 1) {
                            swal.close();
                            cookiePersist(code);

                            swal({
                                title: "code sent successfully . Enter verification code ",
                                text: "Please wait.",
                                showConfirmButton: false,
                                html: "<form ><div> <input id='txtVerificationCode' class='form-control' type='text'></div> <div><input id='btnSubmit1' onclick='verifyPhone()' class='float-buttons wv-btn wv-first waves-effect waves-button waves-float' value='Verify' type='button'/></div><div><input id='BtnResendCode' class='float-buttons wv-btn wv-first waves-effect waves-button waves-float' value='Resend Code' type='button'/></div> </form>"
                            });
                            notifierService.notifyMessage('success', 'Code sent', data.Message);

                        } else {
                            swal.close();

                            notifierService.notifyMessage('error', 'failed', data.Message);
                        }
                    }

                }, function (err) {
                    console.log("some error occured." + err);
                });

            function cookiePersist(code) {
                var date = new Date();
                var minutes = 5;
                date.setTime(date.getTime() + (minutes * 60 * 1000));
                $.cookie("fgC", code, { expires: date });
            }
        };
        $scope.init();
    });
