        $scope.selectedTemplate = function () {
           // console.log($scope.selectedForm);
            if ($scope.selectedForm.length > 0) {
                var Formfields = $scope.selectedForm[0].fields;
                // $scope.getFormSettings(formid);
                var tableData = [];
                var fields = {};

                var formData = JSON.parse(Formfields);
                $timeout(function () {
                    var controlsOrder = 1;
                    _.each(formData, function (pagesData, key) {
                        if (!Array.isArray(pagesData))
                            formData[key] = JSON.parse(pagesData);
                        _.each(formData[key], function (item) {
                            fields = item;
                            fields.fieldRow = controlsOrder;
                            fields.page = key;
                            if (angular.isDefined(item.values)) {
                                if (!Array.isArray(item.values) && item.values.length > 0)
                                    item.values = JSON.parse(item.values);
                                if (!Array.isArray(item.values) && item.values.length > 0)
                                    item.values = JSON.parse(item.values);
                                fields.values = item.values.map(function (el) {
                                    return el.label;
                                }).join();
                            }
                            tableData.push(fields);
                            controlsOrder++;
                        });

                        controlsOrder = 1;
                    });
                    tableData = $filter('orderBy')(tableData, 'page', false);
                    $tabulator.setData(tableData);
                }, 150);
                $('.container-cs').removeClass('hidden');
            }
            $('#tabulatorModal').modal('hide');
        };


