        function objectKeyByValue(obj, val) {
            return Object.keys(obj).find(key => obj[key] === val);
        }
        function validateRowFields() {
            var rows = $tabulator.getRows();
            var options = {};

            rows.forEach(function (row) {
                var data = row.getData();
                if (typeof options[data.fieldRow] === 'undefined')
                    options[data.fieldRow] = [];
                options[data.fieldRow].push(row);
            });

            var isValid = 0;
            $.each(options, function (row, fields) {
                if (fields.length > 8)
                    isValid++;
            });
            return (isValid > 0 ? false : true);
        }
        $scope.manageGroup = function (groupsParamData) {
            var param = {};
            param = groupsParamData;
            param.created_by = $scope.userDetail.Id;
            param.update_by = $scope.userDetail.Id;
            $rootScope.$emit("ShowLoading");
            mainService.manageGroups("ManageGroups", param)
                .then(function (response) {
                    if (response.data != null && angular.isDefined(response.data)) {
                        if (param.action == 1 || param.action == 2) {
                            var exists = response.data[0];
                            if (exists.res == 1) {
                                if ($scope.isEdit == true)
                                    notifierService.notifyMessage('success', 'group  updated ', exists.Message);
                                else
                                    notifierService.notifyMessage('success', 'group  created ', exists.Message);
                                $scope.saveFormSettings(exists.groupId);
                            }
                            else
                                notifierService.notifyMessage('error', 'failed', exists.Message);
                        }
                    }
                    $rootScope.$emit("HideLoading");

                }, function (err) {
                    $rootScope.$emit("HideLoading");
                    console.log("some error occured." + err);
                });
        };
        function generateUniqueNumber() {
            return (new Date).getTime() + Math.floor(Math.random() * 899999 + 100000);
        };
        $scope.init();



