        $scope.serverChange = function (event) {
            var $this = event;
            var value = $this.value;
            if (value === 'Yes') {
                $($this).parents('.form-group').next().removeClass('hidden');
            } else {
                $($this).parents('.form-group').next().addClass('hidden');
            }
        };

        $scope.fieldsChange = function (event) {
            var $this = event;
            if ($($this).is(':checked')) {
                $($this).parent().parent().find('.listoptions').removeClass('hidden');
            } else {
                $($this).parent().parent().find('.listoptions').addClass('hidden');
            }
        };

