        $scope.onUpdateStatusChange1 = function (type, name) {

            //alert(type);
            if (!DataService.isEmpty($scope.selectedRowQueue)) {
                var newParam = {};
                newParam.queueDetailBox = {};
                newParam.action = 2;
                newParam.formId = $scope.selectedRowQueue.formID;
                newParam.queueDetailBox = $scope.selectedRowQueue;
                newParam.queueDetailBox.autoGeneratedFieldName = $scope.currentQueueAutogeneratedField;
                newParam.queueDetailBox.autoGeneratedId = $scope.selectedRowQueue[$scope.currentQueueAutogeneratedField];

                newParam.queueDetailBox.Id = $scope.selectedRowQueue.Id;
                var valData = statusTypeQueue(type);
                newParam.queueDetailBox.Query = name + "='" + valData + "'";
                if (!DataService.isEmpty($scope.serverControls) && !DataService.isEmpty($scope.serverControls.serverData)) {
                    newParam.queueDetailBox.Query += " , " + $scope.serverControls.name + " = '" + $scope.serverControls.serverData + "'";
                    newParam.queueDetailBox.fieldStatusValue = $scope.serverControls.serverData;
                }
                newParam.primaryFormId = $scope.selectedRoomFormId;
                newParam.isPrimaryForm = $scope.selectedRoomFormId != "0" ? false : true;
                newParam.queueDetailBox.Query += "," + $scope.currentQueue.queueDetailBox.currentpositionFieldName + "='" + $scope.currentQueue.queueDetailBox.currentposition + "'";
                newParam.queueDetailBox.Query += "," + $scope.currentQueue.queueDetailBox.lastpositionFieldName + "='" + $scope.currentQueue.queueDetailBox.lastposition + "'";
                updateQueueMainMethod(newParam, 0);

            }
        }
