            param.autoGeneratedFieldName = $scope.currentQueue.queueDetailBox.autoGeneratedFieldName;
            param.currentpositionFieldName = $scope.currentQueue.queueDetailBox.currentpositionFieldName;
            param.lastpositionFieldName = $scope.currentQueue.queueDetailBox.lastpositionFieldName;
