        function statusTypeQueue(type) {
            var sta = "";
            switch (type) {
                case "2":
                    sta = "Pending";
                    break;
                case "3":
                    sta = "Served";
                    break;
                case "4":
                    sta = "Deleted";
                    break;
                default:
                    sta = "";
                    break;
            }
            return sta;
        };
