        function tConv12(time12) {
            var d = new Date();

            var month = d.getMonth() + 1;
            var day = d.getDate();

            var output = d.getFullYear() + '/' +
                (month < 10 ? '0' : '') + month + '/' +
                (day < 10 ? '0' : '') + day;
            var time = time12.split(':');
            var hours = parseInt(time[0]);
            hours = (hours % 12) || 12;
            return " " + hours + ":" + time[1];
        }
