        function filterSessionRecords(newParam) {
            var sessionName = CookiesPersistenceService.getCookieData("MyQueue_100");
            var filterTabulatorTemp = angular.copy($scope.formDetailsDataTemp);
            if (!DataService.isEmpty(sessionName)) {
                filterTabulatorTemp = _.filter(filterTabulatorTemp, function (item, key) {
                    return item[$scope.sessionControls.name] == sessionName;
                });
            }
            else {
                filterTabulatorTemp = angular.copy($scope.formDetailsDataTemp);
            }
            tabulator.setData(filterTabulatorTemp);
        };
        $scope.GetFormRecordListQueue = function (param) {
            var newParam = {};
            newParam = angular.copy(param);
            newParam.action = 17;
            $rootScope.$emit("ShowLoading");
            newParam.created_by = $scope.userDetail.Id;
            newParam.update_by = $scope.userDetail.Id;
            newParam.currentFormType = $scope.formDetailsDataInfo.currentFormType;
            // newParam.formId = param.formId;
            //newParam.topicId = $scope.formDetailsDataInfo.topicId;
            mainService.getFormRecordList("GetFormRecordList", newParam)
                .then(function (response) {
                    if (response.data != null && angular.isDefined(response.data)) {
                        //console.log(response.data)
                        var formDataTemp = response.data;
                        if (!DataService.isEmpty(formDataTemp.data))
                            $scope.formDetailsDataTemp = angular.copy(formDataTemp.data);

                        if ($scope.formDetailsDataInfo.isPrimaryForm == false && $scope.formDetailsDataInfo.primaryFormId != 0) {
                            $scope.formDetailsDataTemp = _.map($scope.formDetailsDataTemp, function (itemmap) {
                                return _.extend(itemmap, { "Room": $scope.formDetailsDataInfo.title });
                            });
                        }
                        $scope.currentQueueData = {};
                        $scope.lastQueueData = {};
                        var sessionName = CookiesPersistenceService.getCookieData("MyQueue_100");
                        var currentQue1 = _.filter($scope.formDetailsDataTemp, function (item, key) {
                            if (!DataService.isEmpty(sessionName))
                                return item[$scope.currentQueueStatus.name] == "Waiting" && item[$scope.sessionControls.name] == sessionName;
                            else
                                return item[$scope.currentQueueStatus.name] == "Waiting";
                        });

                        if (angular.isDefined(currentQue1)) {
                            $scope.currentQueueDatatemp = angular.copy(currentQue1[0]);
                            $scope.currentQueueData = currentQue1[0];
                            $scope.lastQueueData = currentQue1[currentQue1.length - 1];

                        }
                        if (!DataService.isEmpty($scope.currentQueueData)) {
                            $scope.currentQueueData.formID = $scope.formDetailsDataTemp.length > 1 ? $scope.formDetailsDataTemp[0].formID : 0;
                            $scope.currentQueueData.tabsName = $scope.currentQueueData.formID;
                            $scope.currentQueueData.status = "Waiting";
                        }
                        if (!DataService.isEmpty($scope.serverControls) && !DataService.isEmpty($scope.serverControls.name))
                            if (!DataService.isEmpty($scope.currentQueueData))
                                $scope.serverControls.serverData = $scope.currentQueueData[$scope.serverControls.name];
                        filterSessionRecords(newParam);
                        $scope.refreshButtonFunc(newParam.formId);

                        //var formDataFields = [];
                        //_.each(formDataTemp, function (pagesData, key) {
                        //    formDataFields.push({ key });
                        //});
                        //    form - records - 12416
                        //    var tabulator = new Tabulator("#form-records-" + newParam.formId, {
                        //    movableRows: true,
                        //    height: "251px",
                        //    placeholder: "No records...",
                        //    layout: 'fitColumns',
                        //    movableColumns: true,
                        //    columns: headers,
                        //    data: tableData, //set initial table data
                        //});
                        $rootScope.$emit("HideLoading");
                    }
                    $rootScope.$emit("HideLoading");
                }, function (err) {
                    $rootScope.$emit("HideLoading");
                    console.log("some error occured." + err);
                });
        };
        $scope.toggleFullScreen = function ($event) {
           // console.log('clicked');
            if ($("#queue-summary").hasClass('fullscreen')) {
                $("#queue-summary").removeClass('fullscreen');
                angular.element($event.target).html('<i class="fa fa-arrows-alt"></i>&nbsp;Full Screen');
                angular.element($event.target).parents('.page-header').find('form, a[data-toggle="modal"], a.refresh-summary').show();
                toggle_fullscreen();
            } else {
                $("#queue-summary").addClass('fullscreen');
                angular.element($event.target).html('<i class="fa fa-times-circle"></i>&nbsp;Exit Full Screen');
                angular.element($event.target).parents('.page-header').find('form, a[data-toggle="modal"], a.refresh-summary').hide();
                toggle_fullscreen();
            }
        };
