            $scope.expandFieldListTable = [];
            $scope.expandFieldListTableList = [];
            $scope.configExpandBy = {};
            $scope.configExpandBy.tableField = "0";
            $scope.configExpandBy.columnField = "0";
            $scope.expandFieldListTableListControls = {};
            $scope.langId = "1";
